package ro.leo.visual;
import android.content.*;import android.net.Uri;import java.io.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
final class BluetoothTransfers {
 static JSONObject run(Context c,String action,String argument)throws Exception{if(!Arrays.asList("list","send","accept","reject","cancel").contains(action))throw new SecurityException();String apk=c.getPackageCodePath();if(!apk.matches("[A-Za-z0-9_./=+-]+")||argument!=null&&!argument.matches("[A-Za-z0-9_./=-]+"))throw new SecurityException();String command="CLASSPATH="+apk+" /system/bin/app_process /system/bin ro.leo.visual.BluetoothOppBridge "+action+(argument==null?"":" "+argument);final java.lang.Process process=new ProcessBuilder("/system/bin/leo-su","-c",command).redirectErrorStream(true).start();FutureTask<String> reading=new FutureTask<String>(new Callable<String>(){public String call()throws Exception{StringBuilder text=new StringBuilder();try(Reader r=new InputStreamReader(process.getInputStream(),"UTF-8")){char[] buf=new char[2048];int n;while((n=r.read(buf))!=-1){if(text.length()+n>65536)throw new IOException();text.append(buf,0,n);}}return text.toString();}});new Thread(reading,"LeoOppResult").start();try{if(!process.waitFor(10,TimeUnit.SECONDS))throw new IOException();String[] lines=reading.get(2,TimeUnit.SECONDS).trim().split("[\\r\\n]+");JSONObject result=new JSONObject(lines[lines.length-1]);if(process.exitValue()!=0||!result.optBoolean("success"))throw new IOException();return result;}finally{process.destroy();reading.cancel(true);}}
 static void send(Context c,String device,ArrayList<Uri> uris,String mime)throws Exception{if(!android.bluetooth.BluetoothAdapter.checkBluetoothAddress(device)||uris.isEmpty()||uris.size()>20)throw new IllegalArgumentException();JSONArray values=new JSONArray();for(Uri u:uris){if(u==null||!"content".equals(u.getScheme()))throw new SecurityException();c.grantUriPermission("com.android.bluetooth",u,Intent.FLAG_GRANT_READ_URI_PERMISSION);values.put(u.toString());}File job=new File(c.getFilesDir(),"btjob-"+UUID.randomUUID()+".json");try{BackupEngine.write(job,new JSONObject().put("device",device).put("mime",mime==null?"application/octet-stream":mime).put("uris",values).toString().getBytes("UTF-8"));run(c,"send",job.getPath());}finally{job.delete();}}
 static int percent(long current,long total){return total<=0?-1:(int)Math.min(100,Math.max(0,current)*100.0/total);}
}
